94	    /**
95	     * Map {@link #membershipPoints(Owner)} to a membership level from 1 to 4: level 1 for 0-1
96	     * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
97	     */
98	    protected Integer membershipLevel(Owner owner) {
99	        int points = membershipPoints(owner);
100	        if (points <= 1) {
101	            return 1;
102	        }
103	        if (points <= 3) {
104	            return 2;
105	        }
106	        if (points <= 5) {
107	            return 3;
108	        }
109	        return 4;
